package com.netflix.frigga.ami;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class AppVersionTest {

    @Test
    public void parseName_EmptyString_ReturnsNull() {
        AppVersion result = AppVersion.parseName("");
        assert null != result;
    }

    @Test
    public void parseName_SingleWordName_ReturnsParsedAppVersion() {
        String name = "1.2";
        AppVersion result = AppVersion.parseName(name);
        assertEquals(1, result.getVersion());
        assertEquals(2, result.getBuildJobName().charAt(0));
    }

    @Test
    public void parseName_MultipleWordsName_ReturnsParsedAppVersion() {
        String name = "1.2-123456";
        AppVersion result = AppVersion.parseName(name);
        assertEquals(1, result.getVersion());
        assertEquals(2, result.getBuildJobName().charAt(0));
        assertEquals("123456", result.getCommit());
    }

    @Test
    public void parseName_NameWithoutVersion_ReturnsParsedAppVersion() {
        String name = "123456";
        AppVersion result = AppVersion.parseName(name);
        assert result != null;
    }

    @Test
    public void compareTo_SameAppVersions_ReturnsZero() {
        AppVersion version1 = new AppVersion();
        AppVersion version2 = new AppVersion();
        assertEquals(0, version1.compareTo(version2));
    }

    @Test
    public void compareTo_LowerVersionThan_ReturnsNegative() {
        AppVersion version1 = new AppVersion();
        AppVersion version2 = new AppVersion("0.9");
        assertEquals(-1, version1.compareTo(version2));
    }

    @Test
    public void compareTo_HigherVersionThan_ReturnsPositive() {
        AppVersion version1 = new AppVersion();
        AppVersion version2 = new AppVersion("1.0");
        assertEquals(1, version1.compareTo(version2));
    }

    @Test
    public void getAppVersionPattern_MatchReturnsMatchResult() {
        Pattern pattern = AppVersion.getAppVersionPattern();
        Matcher matcher = pattern.matcher("1.2-123456");
        assertTrue(matcher.matches());
    }

    @Test
    public void getPackageName_EmptyString_ReturnsEmptyString() {
        String packageName = AppVersion.getPackageName("");
        assertEquals("", packageName);
    }

    @Test
    public void getBuildNumber_EmptyString_ReturnsEmptyString() {
        String buildNumber = AppVersion.getBuildNumber("");
        assertEquals("", buildNumber);
    }
}
